  const collection = parseCollectionPath(r.collection);
  let limit = STORE_LIMIT_DEFAULT;
  if (r.limit !== undefined && r.limit !== null) {
    if (typeof r.limit !== 'number' || !isFinite(r.limit) || r.limit < 1 || Math.floor(r.limit) !== r.limit) {
      throw webError('invalid_argument', 'limit 값이 올바르지 않아요');
    }
    limit = Math.min(r.limit, STORE_LIMIT_MAX);
  }
  let field = null;
  let dir = 'asc';
  if (r.orderBy !== undefined && r.orderBy !== null) {
    if (typeof r.orderBy !== 'object' || typeof r.orderBy.field !== 'string' || r.orderBy.field === '') {
      throw webError('invalid_argument', '정렬 기준이 올바르지 않아요');
    }
    field = r.orderBy.field;
    dir = r.orderBy.dir === 'desc' ? 'desc' : 'asc';
  }
