    const s = firstCloseOnOrAfter(stock, d);
    const b = firstCloseOnOrAfter(benchCloses, d);
    if (s.reason === 'window' || b.reason === 'window') { errors.push({ source: 'enrich', status: 'skip', reason: 'window' }); return; }
    if (!s.ok || !b.ok) return;
