__def_("gas/web/server.js", {"./store.js":"gas/web/store.js","./claudeapi.js":"gas/web/claudeapi.js","./daily.js":"gas/web/daily.js","./market.js":"gas/web/market.js","./ruleseed.js":"gas/web/ruleseed.js"}, function (module, exports, require) {
'use strict';
// Web app entry points: doGet (the page), the google.script.run endpoints (web*), and the daily trigger handler.
// build-web.js returns every export here from dist-web/bundle.js; the loader (dist-web/Code.gs) has top-level stubs
// for doGet, dailyBriefing and webStatus, and the page reaches every web* export through its webCall dispatcher
// (build-web.js allows only doGet, dailyBriefing and web* names here). Every endpoint fails with
// Error(JSON.stringify({code, message})); the API key is never returned or logged. GAS globals are read inside
// functions only (node tests inject fakes via globalThis; WEB_PAGE_HTML is a variable the bundle defines).

const store = require('./store.js');
const claudeapi = require('./claudeapi.js');
const daily = require('./daily.js');
const market = require('./market.js');
const ruleseed = require('./ruleseed.js');

const SERVER_TITLE = '투자 브리핑';
const SERVER_VIEWPORT = 'width=device-width, initial-scale=1, viewport-fit=cover';
const SERVER_KEY_RE = /^sk-ant-[A-Za-z0-9_-]{16,}$/;
const SERVER_TRIGGER_HANDLER = 'dailyBriefing';
const SERVER_HOURLY_PROP = 'TRIGGER_HOURLY_UID';

// Any error -> Error(JSON {code, message}). Errors this code raised already are; anything else becomes 'internal'
// with a fixed message (raw messages may quote URLs or values).
function serverWrap_(fn) {
  try {
    return fn();
  } catch (err) {
    if (err && err.webCode) throw err;
    try {
      console.error('web endpoint failed: ' + (err && err.name ? err.name : 'Error'));
    } catch (e) { /* no console */ }
    throw store.webError('internal', '서버에서 문제가 생겼어요. 잠시 뒤 다시 해주세요');
  }
}

function doGet() {
  return HtmlService.createHtmlOutput(WEB_PAGE_HTML)
    .setTitle(SERVER_TITLE)
    .addMetaTag('viewport', SERVER_VIEWPORT);
}

function webListDocs(req) {
  return serverWrap_(() => store.listDocs(req));
}

// rules/exit is seeded once from ruleseed.js while the sheet has none, so the exit-rule card starts filled in.
function webGetDoc(path) {
  return serverWrap_(() => {
    const doc = store.getDoc(path);
    if (doc.exists || path !== ruleseed.RULE_SEED_PATH) return doc;
    store.setDoc(path, ruleseed.RULE_SEED);
    return store.getDoc(path);
  });
}

function webSetDoc(path, data) {
  return serverWrap_(() => store.setDoc(path, data));
}

function webUpdateDoc(path, patch) {
  return serverWrap_(() => store.updateDoc(path, patch));
}

function webDeleteDoc(path) {
  return serverWrap_(() => store.deleteDoc(path));
}

function webClaude(req) {
  return serverWrap_(() => claudeapi.webClaude(req));
}

function serverDailyTriggers_() {
  return ScriptApp.getProjectTriggers().filter((t) => t.getHandlerFunction() === SERVER_TRIGGER_HANDLER);
}

function serverUid_(t) {
  try {
    return typeof t.getUniqueId === 'function' ? String(t.getUniqueId()) : '';
  } catch (e) {
    return '';
  }
}

// Exactly one hourly dailyBriefing trigger (spec 2026-10-24-intraday-refresh §3.1). The Trigger API cannot tell a
// daily trigger from an hourly one, so the hourly one's uid is kept in TRIGGER_HOURLY_UID. The new trigger is made
// before the old ones go: a failed create keeps the old daily trigger. create false (page open, a trigger run):
// only replaces an existing trigger, never makes the first one (the page's "start" does). -> { created }
function scheduleEnsure_(create) {
  const props = PropertiesService.getScriptProperties();
  const mine = serverDailyTriggers_();
  const uid = String(props.getProperty(SERVER_HOURLY_PROP) || '');
  const keep = uid ? mine.find((t) => serverUid_(t) === uid) : null;
  if (keep) {
    mine.filter((t) => t !== keep).forEach((t) => ScriptApp.deleteTrigger(t));
    return { created: false };
  }
  if (!create && mine.length === 0) return { created: false };
  const made = ScriptApp.newTrigger(SERVER_TRIGGER_HANDLER).timeBased().everyHours(1).create();
  props.setProperty(SERVER_HOURLY_PROP, serverUid_(made));
  mine.forEach((t) => ScriptApp.deleteTrigger(t));
  return { created: true };
}

// The page open and the trigger run migrate an old daily trigger; a failure there never fails them.
function serverEnsureQuietly_() {
  try {
    scheduleEnsure_(false);
  } catch (e) {
    try {
      console.error('trigger update failed: ' + (e && e.name ? e.name : 'Error'));
    } catch (x) { /* no console */ }
  }
}

// -> { hasKey, trigger, lastRun: {date, ok, finishedAt}|null, sheetUrl, email } (email: whether summary mails go out).
function webStatus() {
  return serverWrap_(() => {
    serverEnsureQuietly_();
    const runs = store.listDocs({ collection: 'runs', orderBy: { field: 'date', dir: 'desc' }, limit: 1 });
    const last = runs.length > 0 ? runs[0].data : null;
    const props = PropertiesService.getScriptProperties();
    const mailOff = String(props.getProperty('EMAIL_SUMMARY') || '').trim().toLowerCase() === 'off';
    let hasEmail = false;
    try {
      hasEmail = !!Session.getEffectiveUser().getEmail();
    } catch (e) { /* no userinfo scope */ }
    return {
      hasKey: claudeapi.hasKey(),
      trigger: serverDailyTriggers_().length > 0,
      lastRun: last ? { date: last.date || null, ok: last.ok === true ? true : last.ok === false ? false : null, finishedAt: last.finishedAt || null } : null,
      sheetUrl: SpreadsheetApp.getActive().getUrl(),
      email: !mailOff && hasEmail,
      lastApiError: String(props.getProperty(claudeapi.CLAUDE_LAST_ERROR_PROP) || '').slice(0, 220) || null,
    };
  });
}

function webSaveKey(key) {
  return serverWrap_(() => {
    const k = typeof key === 'string' ? key.trim() : '';
    if (!SERVER_KEY_RE.test(k)) throw store.webError('invalid_argument', 'sk-ant- 로 시작하는 API 키를 넣어 주세요');
    const props = PropertiesService.getScriptProperties();
    props.setProperty(claudeapi.CLAUDE_KEY_PROP, k);
    // what the old key's account needed (its workspace, no fallback option) is looked up again for the new key
    [claudeapi.CLAUDE_WORKSPACE_PROP, claudeapi.CLAUDE_NO_FALLBACK_PROP].forEach((p) => {
      try { props.deleteProperty(p); } catch (e) { /* none */ }
    });
    return { ok: true };
  });
}

// The hourly dailyBriefing trigger (GAS picks its minute); dailyBriefing itself skips the KST night.
function webSetup() {
  return serverWrap_(() => Object.assign({ ok: true }, scheduleEnsure_(true)));
}

// The page's live quotes while it is open (spec 2026-10-24-intraday-refresh §7.1).
function webLiveQuotes(tickers) {
  return serverWrap_(() => market.liveQuotes(tickers, Date.now()));
}

function webRunNow() {
  return serverWrap_(() => {
    const r = daily.runDaily({});
    return { summary: r.summary, ok: r.ok === true };
  });
}

function dailyBriefing() {
  serverEnsureQuietly_();
  return daily.dailyBriefing();
}

module.exports = {
  doGet, dailyBriefing,
  webListDocs, webGetDoc, webSetDoc, webUpdateDoc, webDeleteDoc, webClaude, webStatus, webSaveKey, webSetup, webRunNow, webLiveQuotes,
};
});

